-- Geri dönüş: geri alınabilir. Yalnız iki denetim genişler; "elden" yöntemli ya da panelden girilmiş sipariş yazıldıysa eski denetimlere dönmek o satırları reddeder, denetimler yeni hâlinde bırakılır.
-- Kart 0236: panelden elle sipariş; "elden" ödeme yöntemi ve "panelden-olusturuldu" geçmiş nedeni (karar 0148).
ALTER TABLE "siparis_gecmisi" DROP CONSTRAINT "siparis_gecmisi_neden";--> statement-breakpoint
ALTER TABLE "siparisler" DROP CONSTRAINT "siparisler_odeme_yontemi";--> statement-breakpoint
ALTER TABLE "siparis_gecmisi" ADD CONSTRAINT "siparis_gecmisi_neden" CHECK ("siparis_gecmisi"."neden" in ('olusturuldu', 'panelden-olusturuldu', 'havale-suresi-doldu', 'havale-bildirildi', 'havale-onaylandi', 'hazirlamaya-alindi', 'kargoya-verildi', 'kargo-duzeltildi', 'teslim-edildi', 'yonetici-iptali', 'iade-yapildi'));--> statement-breakpoint
ALTER TABLE "siparisler" ADD CONSTRAINT "siparisler_odeme_yontemi" CHECK (("siparisler"."odeme_yontemi" = 'havale' and "siparisler"."kapida_secenegi" is null and "siparisler"."odeme_son_zamani" is not null) or ("siparisler"."odeme_yontemi" = 'kapida-odeme' and "siparisler"."kapida_secenegi" in ('nakit', 'kart') and "siparisler"."odeme_son_zamani" is null) or ("siparisler"."odeme_yontemi" = 'kart' and "siparisler"."kapida_secenegi" is null and "siparisler"."odeme_son_zamani" is null and "siparisler"."tahsilat" is not null) or ("siparisler"."odeme_yontemi" = 'elden' and "siparisler"."kapida_secenegi" is null and "siparisler"."odeme_son_zamani" is null and "siparisler"."odeme_zamani" is not null));